"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["43556"],{7012(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.inscricao_propria_sem_fase_de_coleta","status":422,"titulo":"A origem dos candidatos \xe9 inscri\xe7\xe3o pr\xf3pria, e nenhuma fase coleta inscri\xe7\xe3o"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.inscricao_propria_sem_fase_de_coleta","requisitos":[],"oQueAconteceu":["A origem dos candidatos do processo \xe9 a inscri\xe7\xe3o pr\xf3pria \u2014 os candidatos se\\ninscrevem pelo sistema \u2014, mas o cronograma n\xe3o tem nenhuma fase que colete\\ninscri\xe7\xe3o. Sem essa fase n\xe3o h\xe1 per\xedodo de inscri\xe7\xe3o, e \xe9 dele que o Edital tira\\no per\xedodo de inscri\xe7\xe3o.","O cronograma pode ficar assim enquanto o processo \xe9 montado em rascunho. A\\nrecusa acontece quando se tenta congelar uma vers\xe3o (publica\xe7\xe3o ou retifica\xe7\xe3o em ato \xfanico) e tamb\xe9m na consulta de\\nconformidade legal, que precisa do dia em que a inscri\xe7\xe3o come\xe7a para avaliar as\\nregras legais e responde com esta mesma causa quando n\xe3o tem de onde tir\xe1-lo.","Quem coleta inscri\xe7\xe3o \xe9 uma caracter\xedstica da fase can\xf4nica escolhida para o\\ncronograma, e n\xe3o uma escolha feita no processo."],"comoResolver":["Inclua no cronograma uma fase can\xf4nica que colete inscri\xe7\xe3o, com in\xedcio e fim\\ndefinidos (fase de inscri\xe7\xe3o sem per\xedodo \xe9 recusada \xe0 parte, em\\n[fase que coleta inscri\xe7\xe3o sem per\xedodo](/erros/uniplus.selecao.processo_seletivo.fase_que_coleta_inscricao_sem_janela)),\\ne repita a opera\xe7\xe3o.","Em processo j\xe1 publicado, a inclus\xe3o da fase \xe9 uma altera\xe7\xe3o do cronograma e\\nprecisa de uma retifica\xe7\xe3o."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Consulta de conformidade legal do processo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);